# Source of docs/adr/*.md. Run: python tools/gen_adr.py
# Each ADR: id, slug, title, context, decision, why (list), alts (list of
# (option, pros, cons, verdict)), consequences (list of (+/-, text)), revisit.

ADRS = [
dict(id="0001", slug="go-for-services", title="Go для всех серверных сервисов",
context="Нужны сервисы с пиковой нагрузкой 20k RPS, низкой латентностью, малым потреблением памяти и быстрым стартом подов при автомасштабировании. Требование заказчика: сервисы на Go и JS.",
decision="Все серверные сервисы пишутся на Go 1.26 со стандартной библиотекой как основой; сборка в статический бинарник без CGO.",
why=["Конкурентность (goroutines) и сетевой стек стандартной библиотеки дают десятки тысяч RPS на ядро без внешних фреймворков.",
     "Статический бинарник ~10–20 МБ, старт за миллисекунды — HPA добавляет поды быстро, образ distroless без ОС.",
     "Зрелые клиенты для всех выбранных систем: franz-go (Kafka), clickhouse-go (официальный), pgx (PostgreSQL).",
     "Предсказуемая латентность: GC с паузами < 1 мс, GOMEMLIMIT/GOMAXPROCS из лимитов контейнера."],
alts=[("Rust","максимальная производительность, нет GC","долгая разработка, меньше специалистов, избыточно для I/O-bound нагрузки","запас производительности Go достаточен (замер: 3,5 мкс на обработчик)"),
      ("Java/Kotlin (Spring/Quarkus)","богатая экосистема, Kafka Streams","память ×5–10, прогрев JIT, тяжёлые образы","хуже для быстрого масштабирования подов"),
      ("Node.js","единый язык с SDK","однопоточный цикл, хуже на CPU-задачах (HMAC, JSON) при 20k RPS","нарушает требование «сервисы на Go»")],
cons=[("+","Единый язык и инструменты (golangci-lint, go test, бенчмарки) во всех сервисах."),("-","Нет генериков-фреймворков уровня Spring — инфраструктурный код (platform) пишется самостоятельно.")],
revisit="Если появятся CPU-bound задачи (ML-скоринг в аукционе), где выигрыш Rust/C++ окупит стоимость."),

dict(id="0002", slug="stdlib-http", title="net/http стандартной библиотеки вместо веб-фреймворка",
context="Публичных эндпоинтов всего три (`/v1/banner`, `/v1/events`, `/api/v1/*`). С Go 1.22 `ServeMux` поддерживает методы и параметры пути.",
decision="HTTP-слой на `net/http` с собственными middleware (recover, метрики, CORS) в пакете `platform`.",
why=["Нет зависимостей и их уязвимостей; поведение таймаутов, HTTP/2, graceful shutdown — стандартное.",
     "Маршрутизации `ServeMux` (`GET /path/{id}`) достаточно для малого числа ресурсов.",
     "Производительности достаточно: узкое место — сеть и JSON, а не роутер (замер 3,5 мкс на запрос целиком)."],
alts=[("gin / echo / chi","удобные middleware и биндинг","лишние зависимости, свой контекст (gin), выгода минимальна","нет задачи, которую stdlib решает плохо"),
      ("fasthttp / fiber","быстрее на синтетике","несовместим с net/http-экосистемой, свои ограничения (нет HTTP/2), сложнее отладка","выигрыш незначим на фоне сети и TLS на ingress"),
      ("gRPC","контракт, бинарный протокол","браузеру нужен gRPC-Web/прокси; sendBeacon не умеет","клиент — браузер")],
cons=[("+","Минимальная поверхность атаки и простые обновления Go."),("-","Валидацию и сериализацию пишем явно (это же делает код прозрачным).")],
revisit="Если число эндпоинтов вырастет до десятков и понадобится генерация из OpenAPI."),

dict(id="0003", slug="kafka", title="Apache Kafka как буфер и журнал событий",
context="Сбор событий должен отвечать быстро и не зависеть от хранилища; при сбое ClickHouse события нельзя терять; поток ~50k событий/с на пике; нужна возможность перечитать данные.",
decision="События публикуются в Kafka (KRaft, 3 узла, RF 3, min.insync.replicas 2, топик `proview.events.v1` 24 партиции, хранение 3–7 дней); потребитель — event-ingester.",
why=["Развязка: collector отвечает 202 сразу, хранилище может быть недоступно часами — события ждут в журнале.",
     "Повторное воспроизведение: можно перезагрузить данные в новую схему или второй потребитель (антифрод).",
     "Горизонтальное масштабирование партициями; порядок событий одного показа (ключ impression_id).",
     "Стандарт отрасли для clickstream, оператор Strimzi снимает операционную сложность; KRaft — без ZooKeeper."],
alts=[("Прямая вставка в ClickHouse из collector","проще, меньше компонентов","мелкие вставки убивают MergeTree; при сбое ClickHouse — потеря или 5xx клиенту","нарушает NFR4"),
      ("ClickHouse async_insert","серверная буферизация мелких вставок","сбой ClickHouse = отказ приёма; нет журнала для повтора","нет развязки"),
      ("RabbitMQ","простота, гибкая маршрутизация","нет журнала с перечитыванием, хуже на 50k msg/s с персистентностью","не даёт replay"),
      ("NATS JetStream","лёгкий, быстрый","меньше экосистема (коннекторы, операторы, мониторинг), команда менее знакома","Kafka — стандарт для этой задачи"),
      ("Redpanda","Kafka API, без JVM, проще","лицензия BSL у части функций","совместим — можно заменить без изменений кода"),
      ("Apache Pulsar","tiered storage, мульти-тенантность","значительно сложнее эксплуатация (BookKeeper)","избыточно")],
cons=[("+","NFR4 выполняется: chaos-тест подтверждает доставку после простоя ClickHouse."),("-","Ещё одна stateful-система: диски ~1 ТБ на брокер в проде, мониторинг лага.")],
revisit="Если команда эксплуатации предпочтёт Redpanda — замена прозрачна (Kafka API)."),

dict(id="0004", slug="franz-go", title="Клиент Kafka: franz-go",
context="Нужны идемпотентный продюсер с ограниченным буфером и консьюмер-группа с ручным коммитом и контролем ребаланса; без CGO (статический бинарник).",
decision="Используется `github.com/twmb/franz-go` (kgo) в collector и ingester.",
why=["Чистый Go, без librdkafka/CGO — статическая сборка и distroless.",
     "Идемпотентный продюсер по умолчанию, `MaxBufferedRecords`, `BufferedProduceRecords()` — основа обратного давления.",
     "`BlockRebalanceOnPoll`, `CommitRecords`, cooperative-sticky — реализуют at-least-once без гонок с ребалансом.",
     "Высокая производительность и активная поддержка, полный Kafka-протокол (KIP), SASL/SCRAM/TLS."],
alts=[("confluent-kafka-go","официальный от Confluent, librdkafka","CGO, сложнее сборка и образ","противоречит статической сборке"),
      ("IBM/sarama","давно используется","сложный API, исторически проблемы с консьюмер-группами и производительностью","franz-go проще и быстрее"),
      ("segmentio/kafka-go","простой API","ограниченный контроль ребаланса и идемпотентности","не хватает для at-least-once с блокировкой ребаланса")],
cons=[("+","Точный контроль семантики доставки в 150 строках кода."),("-","Специфичный API kgo — нужно знать его модели (Fetches, коммиты).")],
revisit="Не требуется в обозримом будущем."),

dict(id="0005", slug="clickhouse", title="ClickHouse как аналитическое хранилище",
context="Десятки миллиардов событий в месяц, агрегации по времени и измерениям с ответом < 1 с, дешёвое хранение, open source, развёртывание в Kubernetes.",
decision="Сырые события и агрегаты хранятся в ClickHouse 25.8 LTS (1 шард × 3 реплики, Replicated-БД, Keeper).",
why=["Колоночное хранение и сжатие ×10–20: ~35 байт на событие, агрегаты по месяцам — сотни миллисекунд.",
     "Вставка сотен тысяч строк/с на узел; материализованные представления строят агрегаты при вставке.",
     "AggregatingMergeTree + uniqState — уникальные посетители, суммируемые по любым срезам.",
     "Дедупликация вставок по токену — основа идемпотентной загрузки; оператор Altinity для Kubernetes."],
alts=[("Apache Druid / Pinot","real-time OLAP, встроенный приём из Kafka","много компонентов (broker, historical, coordinator…), сложная эксплуатация","ClickHouse проще при той же задаче"),
      ("PostgreSQL + TimescaleDB","SQL, знаком команде","на 50k строк/с и миллиардах строк — дорого по CPU и диску","не тянет объём без шардирования"),
      ("Elasticsearch/OpenSearch","поиск, Kibana","дорогое хранение, слабые агрегаты по большим объёмам","не для числовой аналитики"),
      ("BigQuery / Snowflake","без эксплуатации","SaaS, стоимость за запросы, данные у третьей стороны","ограничение: только open source")],
cons=[("+","Запросы админки по 90 дням < 1 с из агрегатов."),("-","Не OLTP: обновления/удаления дорогие; нужно проектировать ORDER BY под запросы.")],
revisit="При записи выше возможностей одного шарда — переход на Distributed-таблицы."),

dict(id="0006", slug="own-ingester", title="Собственный Go-загрузчик Kafka → ClickHouse",
context="Нужно доставить события из Kafka в ClickHouse крупными пачками, ровно один раз в агрегатах, с DLQ для битых сообщений, с метриками и управляемым масштабированием.",
decision="Отдельный сервис event-ingester на Go: пачка по размеру/времени → вставка с `insert_deduplication_token` → коммит смещений.",
why=["Полный контроль семантики: коммит только после успешной вставки, детерминированный токен пачки.",
     "DLQ с причиной ошибки, метрики пачек и задержек, бесконечные повторы с backoff.",
     "Масштабирование числом подов (≤ партиций), KEDA по лагу; не нагружает ClickHouse фоновыми потоками.",
     "Миграции схемы живут рядом с кодом, который пишет данные."],
alts=[("Kafka table engine ClickHouse + MV","без отдельного сервиса","парсинг и ошибки внутри ClickHouse, сложнее DLQ и наблюдаемость, нагрузка на сервер БД, at-least-once с дублями при сбоях","меньше контроля и хуже отладка"),
      ("Kafka Connect + ClickHouse Sink","готовый коннектор, exactly-once режим","JVM-кластер Connect для одного потока, отдельная эксплуатация","избыточная инфраструктура"),
      ("Vector / Fluent Bit","лёгкие агенты","нет коммита после вставки с дедупликацией по пачкам","слабее гарантии"),
      ("ClickPipes (ClickHouse Cloud)","управляемый","SaaS","ограничение: open source, своя инфраструктура")],
cons=[("+","Доставка ровно один раз подтверждена chaos-тестом (простой ClickHouse, SIGKILL)."),("-","Ещё один сервис в сопровождении (~400 строк кода).")],
revisit="Если ClickHouse Kafka engine получит управляемую семантику коммитов и DLQ на уровне, сравнимом с текущей."),

dict(id="0007", slug="aggregates-materialized-views", title="База-агрегатор: MV в AggregatingMergeTree внутри ClickHouse",
context="Требование: события «грузятся в базу-агрегатор», из которой админка строит срезы. Агрегаты должны быть свежими (секунды), дешёвыми и согласованными с сырыми данными.",
decision="Отдельная база `proview_agg` с таблицами `banner_stats_1m` (TTL 14 дней) и `banner_stats_1h` (730 дней), которые заполняют материализованные представления при каждой вставке в `proview.events_raw`.",
why=["Свежесть = момент вставки, без пакетных заданий и расписаний.",
     "Агрегаты согласованы с сырыми данными по построению; дедупликация вставки распространяется на MV.",
     "Минутная гранулярность для оперативного мониторинга, часовая — для истории; запросы выбирают таблицу по диапазону.",
     "Отдельная база даёт отдельные права: аналитика читает только `proview_agg`."],
alts=[("Отдельная БД-агрегатор (PostgreSQL) + пакетная джоба","знакомый SQL, отдельный контур","задержка до окончания джобы, ещё одна система, риск расхождения с raw","хуже свежесть и сложнее"),
      ("Агрегация в потоке (Kafka Streams / Flink)","гибкие окна, поздние события","отдельный кластер обработки, сложность состояния","избыточно для суммирующих метрик"),
      ("Только сырые данные + projections","меньше объектов","запросы по 90 дням сканируют миллиарды строк","нарушает NFR8"),
      ("SummingMergeTree","проще","не поддерживает uniq-состояния (уникальные посетители)","нужен AggregatingMergeTree")],
cons=[("+","Срезы по 90 дням читают тысячи, а не миллиарды строк."),("-","Новое измерение в срезе требует миграции агрегатов (и пересчёта из raw за 30 дней).")],
revisit="Если понадобятся окна по сессиям или поздние события старше суток — потоковая агрегация."),

dict(id="0008", slug="delivery-semantics", title="Семантика доставки: at-least-once + идемпотентная вставка",
context="Деньги считаются по показам и кликам: дубли и потери недопустимы. При этом коллектор должен отвечать за миллисекунды.",
decision="Продюсер: acks=all + idempotence, ответ клиенту после постановки в буфер. Загрузчик: at-least-once с коммитом после вставки и детерминированным токеном дедупликации пачки. SDK: повтор с тем же seq (стабильный event_id).",
why=["Повтор пачки после сбоя вставки или краха загрузчика отбрасывается ClickHouse (проверено тестами).",
     "Ответ 202 до подтверждения Kafka держит p99 приёма в единицах миллисекунд.",
     "event_id = impression_id:seq позволяет дедуплицировать повторы SDK в сырых данных при разборе."],
alts=[("Exactly-once транзакции Kafka + Connect EOS","строгая гарантия","сложность, транзакционный продюсер медленнее, всё равно нужна идемпотентность на стороне ClickHouse","идемпотентная вставка даёт тот же результат проще"),
      ("Синхронный ответ после ack Kafka","нет окна потери на крахе пода","латентность приёма = латентность Kafka (единицы-десятки мс), больше открытых соединений","окно потери ~10 мс трафика пода приемлемо"),
      ("ReplacingMergeTree по event_id","дедуп повторов SDK","дедуп только при слиянии, FINAL дорогой, агрегаты через MV всё равно получат дубли","не решает задачу для агрегатов"),
      ("At-most-once","просто","потери при любом сбое","неприемлемо")],
cons=[("+","Сбой ClickHouse или загрузчика не теряет и не удваивает события."),("-","Крах пода collector теряет буфер, не подтверждённый Kafka (≤ linger 10 мс + in-flight); повтор SDK после сетевой ошибки может дать дубль события (редкий, видим в raw по event_id).")],
revisit="Если бизнес потребует нулевого окна потерь на крахе пода — режим синхронного ack для кликов."),

dict(id="0009", slug="banner-pool-postgres-snapshot", title="Пул баннеров: PostgreSQL + неизменяемый снимок в памяти",
context="Выдача на 10k RPS с p99 < 20 мс, работа при недоступной БД; пул небольшой (сотни-тысячи баннеров), меняется редко; нужны транзакции и ограничения при редактировании.",
decision="Источник истины — PostgreSQL (CloudNativePG); каждая реплика держит снимок пула в `atomic.Pointer`, перезагружая его раз в 10 с (± джиттер) и сразу после записи через API.",
why=["Горячий путь без сети и блокировок: выбор ~230 нс, 0 аллокаций.",
     "Stale-while-error: при отказе БД выдача продолжается последним снимком.",
     "PostgreSQL даёт CHECK-ограничения, транзакции, привычные миграции; CNPG — failover в Kubernetes."],
alts=[("Запрос в PostgreSQL на каждый показ","всегда свежие данные","10k запросов/с в БД, латентность и единая точка отказа","нарушает NFR2/NFR6"),
      ("Redis как основное хранилище","быстро, общий для реплик","сетевой вызов на каждый показ, ещё одна система, слабее ограничения данных","снимок в памяти быстрее и проще"),
      ("Конфигурационный файл / ConfigMap","GitOps, просто","изменение = выкладка; нет API для трафик-менеджера","не подходит для оперативного управления"),
      ("LISTEN/NOTIFY для мгновенного обновления","секундная свежесть","держит соединение на реплику, сложнее восстановление","10 с достаточно; можно добавить позже")],
cons=[("+","Выдача переживает недоступность БД; нагрузка на БД — 1 запрос в 10 с на реплику."),("-","Изменения пула видны с задержкой до ~12 с на других репликах.")],
revisit="Если пул вырастет до сотен тысяч креативов с частыми изменениями — индексы в памяти и инкрементальные обновления (CDC)."),

dict(id="0010", slug="impression-token", title="Подписанный HMAC-токен показа",
context="Сборщик событий должен отличать настоящие показы от подделок и не доверять клиенту `banner_id`/`placement`, но не обращаться к общей БД на каждый запрос.",
decision="banner-service выдаёт токен `base64url(1|kid|impression_id|banner_id|placement|issued) . HMAC-SHA256[:16]`; collector проверяет подпись, срок жизни и берёт атрибуты показа из токена. Ключи с идентификатором (kid) для ротации.",
why=["Проверка без состояния: ~0,7 мкс, без сети.",
     "Клиент не может приписать события чужому баннеру или месту.",
     "Ротация ключей без простоя: collector принимает текущий и предыдущий kid."],
alts=[("JWT","стандарт, библиотеки","длиннее (заголовок, JSON), выбор алгоритма — источник уязвимостей, лишний парсинг","компактный собственный формат проще и безопаснее"),
      ("Реестр показов в Redis","можно отзывать, считать уникальность","10k записей/с и чтений/с, ещё одна зависимость на горячем пути","stateless-проверки достаточно"),
      ("Без проверки","просто","тривиальная накрутка","неприемлемо для денежных метрик")],
cons=[("+","Подделки отклоняются (e2e-тест), атрибуты показа доверенные."),("-","Токен можно переиспользовать в пределах срока жизни — дальнейшая защита на уровне антифрода по сырым событиям.")],
revisit="При внедрении антифрода — одноразовость кликов через короткоживущий Bloom-фильтр."),

dict(id="0011", slug="event-format-json", title="Формат событий: версионированный JSON с контрактными тестами",
context="Контракт событий связывает SDK, collector и ingester в разных репозиториях; сегодня один потребитель топика.",
decision="JSON-сообщения с полем `v` (=1) и ключом `impression_id`; контракт зафиксирован в документации и проверяется контрольными векторами (токен, пример сообщения) в тестах обоих сервисов и e2e-тестом.",
why=["Читаемо при отладке (kafka-console-consumer), без инфраструктуры Schema Registry.",
     "Объём после zstd-сжатия пачек близок к бинарным форматам (~4 МБ/с на пике).",
     "Правило эволюции простое: добавлять поля можно, ломать — только новым топиком."],
alts=[("Protobuf + Schema Registry","строгая схема, компактность, генерация кода","ещё один сервис, кодогенерация в трёх репозиториях","окупается при нескольких потребителях — запланировано в развитии"),
      ("Avro + Schema Registry","эволюция схем, экосистема Kafka Connect","то же + менее удобен в Go","нет Connect в архитектуре"),
      ("MessagePack/CBOR","компактно, без схемы","хуже инструменты отладки, выигрыш съедает сжатие","незначимый выигрыш")],
cons=[("+","Простая отладка и отсутствие лишней инфраструктуры."),("-","Схема проверяется тестами, а не брокером; дисциплина эволюции обязательна.")],
revisit="Когда у топика появится второй-третий потребитель (антифрод, биллинг)."),

dict(id="0012", slug="dashboard-stack", title="Админка: ES-модули + ECharts, встроенные в Go-бинарник",
context="Нужна красивая настраиваемая визуализация для потребителя среза, без отдельной фронтенд-инфраструктуры; требование «сервисы на Go и JS».",
decision="Одностраничная админка на нативных ES-модулях без сборки, графики Apache ECharts 5.6 (вендорится в репозиторий), раздаётся тем же Go-сервисом через `embed`.",
why=["Один артефакт: API и UI выкладываются вместе и не расходятся по версиям.",
     "ECharts — богатая визуализация (линии, воронка, тепловая карта), SVG-рендер, Apache-2.0.",
     "Без npm-сборки и node_modules: нет цепочки поставки фронтенда, CSP `self`; логика форматирования тестируется `node --test`."],
alts=[("React/Vite SPA","экосистема компонентов","сборка, сотни зависимостей, отдельный пайплайн","избыточно для одного дашборда"),
      ("Grafana с плагином ClickHouse","готовые панели, алерты","интерфейс для инженеров, не продукт для менеджера; кастомные срезы и подписи сложнее","целевой пользователь — не инженер"),
      ("Apache Superset / Metabase","конструктор отчётов","отдельная система с БД метаданных, своя авторизация","тяжело для фиксированного продукта"),
      ("CDN-подключение ECharts","не хранить в репозитории","внешний домен, CSP шире, не работает в закрытом контуре","вендоринг надёжнее")],
cons=[("+","Админка весит ~1 МБ (ECharts), работает в изолированной сети."),("-","Нет компонентной библиотеки — сложные формы (UI пула) потребуют больше ручного кода.")],
revisit="Когда в админку добавится управление пулом и права — оценить переход на компонентный фреймворк."),

dict(id="0013", slug="helm-and-operators", title="Helm-чарт на сервис + umbrella; инфраструктура через операторы",
context="Нужна удобная доставка в произвольный Kubernetes, независимые релизы сервисов и надёжные Kafka/PostgreSQL/ClickHouse.",
decision="Каждый сервис публикует свой Helm-чарт (OCI, GHCR) из своего репозитория; `proview-deploy` содержит umbrella-чарт с зависимостями и ресурсами операторов Strimzi, CloudNativePG, Altinity clickhouse-operator; профили dev/prod.",
why=["Сервис выпускается и откатывается независимо; umbrella фиксирует совместимый набор версий.",
     "Операторы реализуют failover, обновления, бэкапы — то, что нельзя надёжно сделать StatefulSet-ом вручную.",
     "OCI-реестр GHCR — один реестр для образов и чартов."],
alts=[("Kustomize","без шаблонов, патчи","нет версионирования пакетов и зависимостей, хуже параметризация для чужой инфраструктуры","Helm удобнее для дистрибуции"),
      ("Bitnami-чарты Kafka/PostgreSQL/ClickHouse","быстро","с 2025 г. изменилась политика публикации образов Bitnami (бесплатные — только ограниченный набор/legacy), StatefulSet без операторской логики failover","риск поставки и слабее эксплуатация"),
      ("Управляемые облачные сервисы (MSK, Cloud SQL, ClickHouse Cloud)","нет эксплуатации","привязка к облаку, стоимость, требование своей инфраструктуры","не подходит как базовый вариант; чарт позволяет отключить infra и указать внешние адреса"),
      ("Argo CD ApplicationSet без Helm","GitOps","всё равно нужен формат пакета","дополняет Helm, а не заменяет")],
cons=[("+","Установка всей системы одной командой; инфраструктура декларативна."),("-","Операторы ставятся заранее (cluster-scoped CRD) — это шаг платформенной команды.")],
revisit="При переходе на GitOps — Argo CD Application поверх этого же umbrella-чарта."),

dict(id="0014", slug="observability", title="Наблюдаемость: Prometheus-метрики и JSON-логи",
context="Нужно видеть RPS, латентность, обратное давление, лаг загрузки и свежесть пула; логи не должны сами стать нагрузкой при 20k RPS.",
decision="Каждый сервис отдаёт `/metrics` (client_golang, OpenMetrics) на отдельном ops-порту, ServiceMonitor в чартах; логи — slog JSON в stdout без access-log на горячем пути, с ограничением частоты повторяющихся ошибок.",
why=["Метрики дешевле логов на каждый запрос и дают SLO/алерты.",
     "Ops-порт отделён от публичного — метрики не доступны снаружи.",
     "JSON-логи собираются любым агентом (Vector, Fluent Bit, Promtail)."],
alts=[("Access-log на каждый запрос","полный след","~20k строк/с только от выдачи, стоимость хранения","метрики + сэмплирование ошибок достаточно"),
      ("OpenTelemetry (трейсы + метрики)","сквозная трассировка","SDK и коллектор, накладные расходы, хранилище трейсов","запланировано в развитии для пути collector → ingester"),
      ("StatsD / push-метрики","проще для коротких задач","не стандарт Kubernetes-мониторинга","Prometheus — де-факто стандарт")],
cons=[("+","Готовые алерты в architecture.md §10."),("-","Нет сквозной трассировки отдельного события (есть event_id в raw).")],
revisit="При внедрении OpenTelemetry Collector в кластере."),

dict(id="0015", slug="container-images", title="Образы: distroless static nonroot и nginx-unprivileged",
context="Минимальная поверхность атаки и размер образа, запуск без root и с read-only FS по best practices Kubernetes (Pod Security Standards restricted).",
decision="Go-сервисы: multi-stage сборка `golang:1.26-alpine` → `gcr.io/distroless/static-debian12:nonroot` (~24–30 МБ); сайт — `nginxinc/nginx-unprivileged`. Сборка multi-arch (amd64/arm64) с SBOM и provenance, проверка Trivy.",
why=["Нет оболочки и пакетного менеджера — нечего эксплуатировать; CVE-поверхность минимальна.",
     "UID 65532, readOnlyRootFilesystem, drop ALL — соответствует профилю restricted.",
     "arm64 позволяет запускать на дешёвых Graviton/Ampere-узлах."],
alts=[("alpine","есть shell для отладки","musl, пакеты = CVE","отладка через ephemeral containers"),
      ("scratch","минимально","нет CA-сертификатов, tzdata, /etc/passwd","distroless включает необходимое"),
      ("Debian/Ubuntu","привычно","сотни МБ и пакетов","избыточно")],
cons=[("+","Образы 24–30 МБ, быстрый pull при масштабировании."),("-","Нет shell: отладка через `kubectl debug`.")],
revisit="Не требуется."),

dict(id="0016", slug="autoscaling", title="Автомасштабирование: HPA по CPU, KEDA по лагу Kafka",
context="Нагрузка суточно меняется в 3 раза и имеет пики; stateless-сервисы масштабируются по CPU, а загрузчик — по объёму невыгруженных данных.",
decision="HPA (autoscaling/v2) по CPU 60 % с быстрым ростом и медленным снижением для сервисов приёма и выдачи; для ingester — опциональный KEDA ScaledObject по лагу группы (в prod-профиле). PDB, topology spread по зонам и узлам, maxUnavailable 0 при выкладке.",
why=["CPU — точный индикатор нагрузки для CPU-bound обработчиков (JSON, HMAC).",
     "Лаг — прямой индикатор отставания загрузчика, CPU у него может быть низким при ожидании ClickHouse.",
     "Readiness collector падает при заполнении буфера — трафик перераспределяется ещё до масштабирования."],
alts=[("Фиксированное число реплик","предсказуемо","переплата вне пика или отказ на пике","неэкономично"),
      ("HPA по RPS (custom metrics)","точнее для выдачи","нужен prometheus-adapter","CPU достаточно; можно добавить"),
      ("VPA","подбор ресурсов","конфликтует с HPA по CPU, перезапуски подов","использовать в режиме рекомендаций")],
cons=[("+","Мощность следует за нагрузкой, отказ зоны переживается."),("-","KEDA — дополнительный оператор (опционально).")],
revisit="После накопления реальных профилей нагрузки — пороги и минимальные реплики."),

dict(id="0017", slug="admin-auth", title="Доступ к админке: Basic-auth или SSO на ingress",
context="Админкой пользуются внутренние сотрудники; в компаниях обычно есть SSO; встраивать полноценный OIDC в каждый сервис дорого.",
decision="Встроенная Basic-аутентификация (сравнение за постоянное время, пароль из Secret) для простых установок; в production — SSO через oauth2-proxy на ingress (`auth-url`) и `AUTH_DISABLED=true` в сервисе.",
why=["SSO централизует пользователей, MFA и аудит без кода в сервисе.",
     "Basic-auth делает систему безопасной по умолчанию даже без SSO.",
     "Сервис отказывается стартовать без пароля, если явно не отключена аутентификация."],
alts=[("Встроенный OIDC-клиент","без прокси","код сессий, refresh-токенов, CSRF в каждом сервисе","прокси решает это один раз"),
      ("Без аутентификации, только сеть","просто","любой из внутренней сети видит коммерческие данные","неприемлемо")],
cons=[("+","Одна настройка ingress для любого IdP (Keycloak, Google, Azure AD)."),("-","Нет ролевой модели внутри админки (все видят все баннеры).")],
revisit="Когда понадобится разграничение по рекламодателям — роли из claims SSO-заголовков."),

dict(id="0018", slug="browser-sdk", title="SDK: ES-модуль без зависимостей, IntersectionObserver и sendBeacon",
context="SDK встраивается на чужие сайты: должен быть маленьким, не тормозить страницу, корректно измерять видимость и не терять события при уходе.",
decision="Три ES-модуля без зависимостей (~8 КБ): трекер и очередь — чистые классы с тестами на фиктивных часах; DOM-слой — IntersectionObserver, pointer-события, visibilitychange/pagehide; отправка `text/plain` через fetch keepalive и `navigator.sendBeacon`.",
why=["IntersectionObserver — нативное и дешёвое измерение видимости по IAB без опроса скролла.",
     "`text/plain` не вызывает CORS-preflight — один запрос вместо двух на каждый пакет.",
     "sendBeacon доставляет события при закрытии вкладки; повторы с тем же seq сохраняют event_id."],
alts=[("Пиксель-изображение (GET)","работает везде","нет тела, ограничение длины URL, кэширование, нет пакетов","не годится для длительностей и пакетов"),
      ("Google Tag Manager / сторонний счётчик","без разработки","данные у третьей стороны, нет нашего токена","противоречит цели продукта"),
      ("Сборка (TypeScript + бандлер)","типизация","цепочка сборки для ~300 строк","можно ввести при росте SDK")],
cons=[("+","Логика трекинга покрыта 11 unit-тестами без браузера."),("-","Без сборки нет минификации — решается CDN-сжатием (gzip/brotli).")],
revisit="Если SDK вырастет (видео-форматы, consent API) — TypeScript и сборка."),

dict(id="0019", slug="repos-and-ci", title="Репозиторий на сервис, GitHub Actions, GHCR",
context="Требование: отдельный репозиторий на каждый сервис и на документацию, удобная доставка в инфраструктуру.",
decision="Шесть репозиториев кода (`proview-*`) и `proview-docs`; в каждом CI: lint → unit → интеграционные тесты на реальных зависимостях (services) → helm lint + kubeconform → multi-arch образ в GHCR (+SBOM, provenance, Trivy) → по тегу публикация чарта. `proview-deploy` ночью собирает все main-ветки и гоняет e2e, chaos и короткую нагрузку. Общий код (`internal/platform`, ~200 строк) копируется, а не выносится в библиотеку.",
why=["Независимые релизы и права на уровне сервиса.",
     "Межсервисные контракты проверяются дважды: контрольными векторами в unit-тестах и e2e в deploy.",
     "Копия маленького инфраструктурного пакета дешевле, чем версионирование общей библиотеки по шести репозиториям."],
alts=[("Монорепозиторий","атомарные изменения контрактов, один CI","противоречит требованию; сложнее разграничение прав","требование заказчика"),
      ("Общая Go-библиотека proview-kit","нет дублирования","каскад обновлений по репозиториям, связанное версионирование","дублирование 200 строк дешевле"),
      ("GitLab CI / Jenkins","самостоятельный хостинг","код уже на GitHub","Actions — нативно для GitHub")],
cons=[("+","Каждый сервис доставляется независимо; совместимость проверяется ночным e2e."),("-","Изменение контракта требует согласованных PR в 2–3 репозиториях.")],
revisit="Если изменения контрактов станут частыми — монорепозиторий или общий модуль контрактов."),
]
